                col=g[r][c]; stack=[(r,c)]; seen[r][c]=True; cells=set()
                while stack:
                    rr,cc=stack.pop(); cells.add((rr,cc))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
