    placed=set()
    result=[row[:] for row in g]
    # order objs by topmost cell
    order=sorted(objs.keys(), key=lambda col:min(r for r,c in objs[col]))
    for col in order:
        cells=sorted(objs[col])
        best=None
        for dr in range(-H,H):
            for dc in range(-W,W):
