    objs.sort(key=lambda o:(len(o),o[0][0],o[0][1]))
    for o in objs:
        best=None
        for dr in range(H):
            for dc in range(W):
                pos={(dr+a,dc+b) for a,b in o}
                if not(pos & occupied) and all(0<=p[0]<H and 0<=p[1]<W for p in pos):
                    best=(dr,dc); break
