    # remove empty rows/cols
    keepr=[r for r in range(H) if any(out[r][c]!=bg for c in range(W))]
    keepc=[c for c in range(W) if any(out[r][c]!=bg for r in keepr)]
    final=[[out[r][c] for c in keepc] for r in keepr]
