G=load()

def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=deque([(r,c)]); seen.add((r,c)); cs=[]
                while st:
                    x,y=st.popleft(); cs.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        xx,yy=x+dx,y+dy
                        if 0<=xx<H and 0<=yy<W and g[xx][yy]==col and (xx,yy) not in seen:
                            seen.add((xx,yy)); st.append((xx,yy))
                out.append((col,cs))
    return out

def render(g,shifts,bg):
    H,W=len(g),len(g[0]); cnt=Counter(v for row in g for v in row); bgc=cnt.most_common(1)[0][0]
    out=[[bgc]*W for _ in range(H)]
    for col,cs in comps(g,bgc):
        shft=shifts.get(tuple(cs),0)
        for r,c in cs: out[r-shft*sign](c)=col if False else (out[max(0,r-shft)] [c]=col)
    return out

def solve_up(I,O):
    bg=Counter(v for row in I for v in row).most_common(1)[0][0]
    # hypothesis: each colored object slides UP as far as possible (gravity up), then noise cells disappear
    H,W=len(I),len(I[0])
    objs=comps(I,bg)
    # sort by bottom-most row descending so lower objects placed first
    objs.sort(key=lambda oc:-max(p[0] for p in oc[1]))
    occ={(p[0],p[1]) for _,p in objs}
    res=[row[:] for row in I]
    for col,cs in objs:
        rs=[r for r,_ in cs]; mins=min(rs)
        while True:
            ok=True
            for r,c in cs:
                nr=r-1
                if nr<0 or (nr,c) in occ or (nr,c)>=0 and res[nr][c]!=bg:
                    ok=False;break
            if ok:
                for r,c in cs: res[r-1][c]=col
                occ.discard((r,c)); occ.add((r-1,c))
            else: break
        # remove original
        for r,c in cs: res[r][c]=bg
        for r,c in cs:
            pass
    return res

for i in [2,3]:
    I=G[f'Demo pair {i} input']; O=G[f'Demo pair {i} output']
    R=solve_up(I,O)
